begin;
do $$declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();sa uuid:=gen_random_uuid();sb uuid:=gen_random_uuid();cash uuid;bank uuid;usd uuid;foreign_account uuid;cat uuid;t jsonb;token2 jsonb;client text;conn uuid;p jsonb;r jsonb;again jsonb;pending jsonb;key text;goal jsonb;debt jsonb;category jsonb;budget jsonb;tx jsonb;failed boolean;begin
 insert into auth.users(id,email,encrypted_password,raw_user_meta_data)values(a,'yolo-qa-'||a||'@example.com','fixture',jsonb_build_object('app','financegpt','username','yqa_'||left(a::text,8))),(b,'yolo-qa-'||b||'@example.com','fixture',jsonb_build_object('app','financegpt','username','yqa_'||left(b::text,8)));
 insert into auth.sessions(id,user_id,created_at,updated_at)values(sa,a,now(),now()),(sb,b,now(),now());
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated','session_id',sb)::text,true);execute 'set local role authenticated';perform financegpt.initialize_profile();foreign_account:=(financegpt.create_account('{"name":"Foreign"}',gen_random_uuid()::text)->>'id')::uuid;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated','session_id',sa)::text,true);perform financegpt.initialize_profile();cash:=(financegpt.create_account('{"name":"Cash","opening_balance":20000000}',gen_random_uuid()::text)->>'id')::uuid;bank:=(financegpt.create_account('{"name":"Bank"}',gen_random_uuid()::text)->>'id')::uuid;usd:=(financegpt.create_account('{"name":"USD","currency":"USD","opening_balance":100000}',gen_random_uuid()::text)->>'id')::uuid;
 select id into cat from financegpt.categories where user_id=a and type='expense'limit 1;t:=financegpt.generate_personal_token('YOLO QA',30);conn:=(t->>'connection_id')::uuid;
 perform financegpt.save_agent_policy(conn,'{"permissions":{"transactions:create":true,"transactions:update":true,"transactions:delete":true,"budgets:write":true,"reports:export":true,"categories:write":true,"recurring:write":true,"goals:write":true,"debts:write":true},"approval_mode":"risk","limits":{"create_limit":1000,"edit_limit":100,"daily_cap":50000000,"hourly_cap":100,"backdate_days":1}}',gen_random_uuid()::text);
 execute 'reset role';select oauth_client_id into client from financegpt.agent_connections where id=conn;
 p:=jsonb_build_object('type','transfer','account_id',cash,'destination_account_id',bank,'amount',100000,'currency','IDR','effective_at',now());key:=gen_random_uuid()::text;pending:=financegpt.agent_mutate(a,client,'transactions:create',p,key);assert pending->>'status'='pending_approval','Risk transfer must still require approval';
 execute 'set local role authenticated';perform financegpt.save_agent_policy(conn,'{"approval_mode":"yolo","limits":{"create_limit":1000,"edit_limit":100,"daily_cap":50000000,"hourly_cap":100,"backdate_days":1}}',gen_random_uuid()::text);execute 'reset role';
 execute 'set local role authenticated';perform financegpt.save_agent_policy(conn,'{"permissions":{},"limits":{"daily_cap":50000000,"hourly_cap":100}}',gen_random_uuid()::text);assert(select approval_mode='yolo'from financegpt.agent_policies where connection_id=conn),'Partial policy update reset YOLO';execute 'reset role';
 assert(select count(*)=0 from financegpt.transactions where user_id=a),'Changing mode executed queued actions';
 r:=financegpt.agent_mutate(a,client,'transactions:create',p,key);assert r->>'status'='ok','Pending transfer did not resume';assert r=financegpt.agent_mutate(a,client,'transactions:create',p,key),'Retry duplicated transfer';assert(select count(*)=1 from financegpt.transactions where user_id=a),'Transfer was posted twice';
 p:=jsonb_build_object('type','expense','account_id',cash,'category_id',cat,'amount',2000000,'currency','IDR','effective_at',now()-interval'2 years');tx:=financegpt.agent_mutate(a,client,'transactions:create',p,gen_random_uuid()::text);assert tx->>'status'='ok','Large/backdated expense needs approval in YOLO';
 r:=financegpt.agent_mutate(a,client,'transactions:update',jsonb_build_object('id',tx->'data'->>'id','amount',2100000,'expected_version',1),gen_random_uuid()::text);assert r->>'status'='ok','Large edit needs approval in YOLO';
 r:=financegpt.agent_mutate(a,client,'transactions:delete',jsonb_build_object('id',tx->'data'->>'id','expected_version',2,'notes','QA void'),gen_random_uuid()::text);assert r->'data'->>'status'='voided','YOLO void not executed';
 p:=jsonb_build_object('type','expense','account_id',usd,'category_id',cat,'amount',1000,'currency','USD','effective_at',now());assert financegpt.agent_mutate(a,client,'transactions:create',p,gen_random_uuid()::text)->>'status'='ok','Non-IDR approval not bypassed';
 execute 'set local role authenticated';budget:=financegpt.save_resource('budgets','{"name":"Budget QA","amount":5000,"currency":"IDR","period_start":"2026-11-01","period_end":"2026-11-30"}',gen_random_uuid()::text);execute 'reset role';
 assert financegpt.agent_mutate(a,client,'budgets:write',jsonb_build_object('id',budget->>'id','amount',7000,'expected_version',1),gen_random_uuid()::text)->>'status'='ok','Budget requires approval';
 r:=financegpt.agent_mutate(a,client,'reports:export','{"format":"csv","type":"transactions"}',gen_random_uuid()::text);assert r->>'status'='ok'and r->'data'->>'status'='approved','Export requires approval';
 category:=financegpt.manage_resource(a,client,'categories','POST','{"name":"YOLO category","type":"expense"}',null,gen_random_uuid()::text);
 assert financegpt.manage_resource(a,client,'categories','DELETE','{"expected_version":1}',(category->'data'->>'id')::uuid,gen_random_uuid()::text)->>'status'='ok','Managed delete requires approval';
 goal:=financegpt.manage_resource(a,client,'savings_goals','POST','{"name":"Goal","target_amount":100000,"target_date":"2027-12-31"}',null,gen_random_uuid()::text);assert financegpt.manage_resource(a,client,'goal_allocations','POST',jsonb_build_object('goal_id',goal->'data'->>'id','amount',1000),null,gen_random_uuid()::text)->>'status'='ok','Allocation requires approval';
 debt:=financegpt.manage_resource(a,client,'debts','POST','{"name":"Debt","counterparty":"QA","principal":100000,"due":"2027-12-31"}',null,gen_random_uuid()::text);assert financegpt.manage_resource(a,client,'debt_payments','POST',jsonb_build_object('debt_id',debt->'data'->>'id','principal_paid',1000),null,gen_random_uuid()::text)->>'status'='ok','Payment requires approval';
 assert financegpt.manage_resource(a,client,'recurring_rules','POST',jsonb_build_object('name','Recurring','next_at',now()+interval'1 year','mode','auto-post','payload_json',jsonb_build_object('type','expense','account_id',cash,'category_id',cat,'amount',1000,'currency','IDR')),null,gen_random_uuid()::text)->>'status'='ok','Recurring auto-post requires approval';
 -- A managed proposal also resumes only on an identical explicit retry.
 execute 'set local role authenticated';perform financegpt.save_agent_policy(conn,'{"approval_mode":"risk","limits":{"daily_cap":50000000,"hourly_cap":100}}',gen_random_uuid()::text);execute 'reset role';key:=gen_random_uuid()::text;p:=jsonb_build_object('goal_id',goal->'data'->>'id','amount',2000);pending:=financegpt.manage_resource(a,client,'goal_allocations','POST',p,null,key);assert pending->>'status'='pending_approval';
 execute 'set local role authenticated';perform financegpt.save_agent_policy(conn,'{"approval_mode":"yolo","limits":{"daily_cap":50000000,"hourly_cap":100}}',gen_random_uuid()::text);execute 'reset role';r:=financegpt.manage_resource(a,client,'goal_allocations','POST',p,null,key);assert r->>'status'='ok';assert r=financegpt.manage_resource(a,client,'goal_allocations','POST',p,null,key),'Managed retry duplicated allocation';
 -- Previously rejected or expired proposals never run when YOLO is enabled.
 execute 'set local role authenticated';perform financegpt.save_agent_policy(conn,'{"approval_mode":"always","limits":{"daily_cap":50000000,"hourly_cap":100}}',gen_random_uuid()::text);execute 'reset role';
 p:=jsonb_build_object('type','expense','account_id',cash,'category_id',cat,'amount',1000,'currency','IDR','effective_at',now());key:=gen_random_uuid()::text;pending:=financegpt.agent_mutate(a,client,'transactions:create',p,key);execute 'set local role authenticated';perform financegpt.resolve_approval((pending->>'action_id')::uuid,false);perform financegpt.save_agent_policy(conn,'{"approval_mode":"yolo","limits":{"daily_cap":50000000,"hourly_cap":100}}',gen_random_uuid()::text);execute 'reset role';assert financegpt.agent_mutate(a,client,'transactions:create',p,key)->>'status'='rejected','Rejected request ran in YOLO';
 execute 'set local role authenticated';perform financegpt.save_agent_policy(conn,'{"approval_mode":"always","limits":{"daily_cap":50000000,"hourly_cap":100}}',gen_random_uuid()::text);execute 'reset role';key:=gen_random_uuid()::text;pending:=financegpt.agent_mutate(a,client,'transactions:create',p,key);update financegpt.agent_pending_actions set expires_at=now()-interval'1 second'where id=(pending->>'action_id')::uuid;execute 'set local role authenticated';perform financegpt.save_agent_policy(conn,'{"approval_mode":"yolo","limits":{"daily_cap":50000000,"hourly_cap":100}}',gen_random_uuid()::text);execute 'reset role';assert financegpt.agent_mutate(a,client,'transactions:create',p,key)->>'status'='expired','Expired request ran in YOLO';
 failed:=false;begin perform financegpt.agent_mutate(a,client,'transactions:create',jsonb_build_object('type','expense','account_id',foreign_account,'category_id',cat,'amount',1000,'currency','IDR','effective_at',now()),gen_random_uuid()::text);exception when others then failed:=true;end;assert failed,'YOLO bypassed account ownership';
 execute 'set local role authenticated';perform financegpt.save_agent_policy(conn,jsonb_build_object('approval_mode','yolo','limits','{"daily_cap":50000000,"hourly_cap":100}'::jsonb,'account_allowlist',jsonb_build_array(cash)),gen_random_uuid()::text);execute 'reset role';failed:=false;begin perform financegpt.agent_mutate(a,client,'transactions:create',jsonb_build_object('type','transfer','account_id',cash,'destination_account_id',bank,'amount',1000,'currency','IDR','effective_at',now()),gen_random_uuid()::text);exception when others then failed:=true;end;assert failed,'YOLO bypassed destination allowlist';
 execute 'set local role authenticated';perform financegpt.save_agent_policy(conn,'{"approval_mode":"yolo","limits":{"daily_cap":1,"hourly_cap":100}}',gen_random_uuid()::text);execute 'reset role';failed:=false;begin perform financegpt.agent_mutate(a,client,'transactions:create',jsonb_build_object('type','expense','account_id',cash,'category_id',cat,'amount',2000,'currency','IDR','effective_at',now()),gen_random_uuid()::text);exception when others then failed:=SQLERRM like'%daily cap%';end;assert failed,'YOLO bypassed daily cap';
 execute 'set local role authenticated';perform financegpt.save_agent_policy(conn,'{"approval_mode":"yolo","limits":{"daily_cap":50000000,"hourly_cap":0}}',gen_random_uuid()::text);execute 'reset role';failed:=false;begin perform financegpt.manage_resource(a,client,'categories','POST','{"name":"Rate limited","type":"expense"}',null,gen_random_uuid()::text);exception when others then failed:=SQLERRM like'%rate_limited%';end;assert failed,'YOLO bypassed hourly cap';
 -- A per-user preference affects new tokens only for that owner; scopes stay read-only.
 update financegpt.profiles set settings_json=settings_json||'{"api_approval_mode":"yolo"}'where user_id=a;execute 'set local role authenticated';token2:=financegpt.generate_personal_token('Default QA',30);assert(select approval_mode='yolo'from financegpt.agent_policies where connection_id=(token2->>'connection_id')::uuid);execute 'reset role';failed:=false;begin perform financegpt.agent_mutate(a,'pat:'||(token2->>'connection_id'),'transactions:create','{}',gen_random_uuid()::text);exception when others then failed:=true;end;assert failed,'YOLO default granted write scopes';
 perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated','session_id',sb)::text,true);execute 'set local role authenticated';failed:=false;begin perform financegpt.save_agent_policy(conn,'{"approval_mode":"yolo"}',gen_random_uuid()::text);exception when others then failed:=true;end;assert failed,'Other user changed YOLO policy';token2:=financegpt.generate_personal_token('Other default QA',30);assert(select approval_mode='risk'from financegpt.agent_policies where connection_id=(token2->>'connection_id')::uuid);execute 'reset role';
 raise notice 'PASS YOLO financial/resource writes, export, pending retries, idempotency, scope and owner isolation, allowlists, caps and per-user defaults';
end $$;
rollback;
